import React from 'react';
import { render, screen } from '@testing-library/react';
import { TextLink } from './TextLink';

const mockedUrl = 'https://www.mybees.com.br/';

describe('TextLink', () => {
  test('should render without crashing', () => {
    render(<TextLink href={mockedUrl}>Bees</TextLink>);
    expect(screen.getByText('Bees')).toBeInTheDocument();
  });

  test('should render with text colorOption black and underline props without crashing', () => {
    render(
      <TextLink href={mockedUrl} colorOption="black" hasUnderline>
        Bees
      </TextLink>
    );
    expect(screen.getByText('Bees')).toBeInTheDocument();
  });

  test('should render with small size prop', () => {
    render(
      <TextLink href={mockedUrl} size="small">
        Bees
      </TextLink>
    );
    expect(screen.getByText('Bees')).toBeInTheDocument();
  });

  test('should render with xsmall size prop', () => {
    render(
      <TextLink href={mockedUrl} size="xsmall">
        Bees
      </TextLink>
    );
    expect(screen.getByText('Bees')).toBeInTheDocument();
  });

  test('should render with component asChild', () => {
    render(
      <TextLink asChild>
        <a href={mockedUrl}>Bees</a>
      </TextLink>
    );
    expect(screen.getByText('Bees')).toBeInTheDocument();
  });
});
